DO $$
DECLARE t text; seq text; top_id bigint;
BEGIN
 FOREACH t IN ARRAY ARRAY['projects','project_members','project_applications','reviews'] LOOP
  seq := pg_get_serial_sequence('public.' || t,'id');
  EXECUTE format('SELECT max(id) FROM public.%I',t) INTO top_id;
  PERFORM setval(seq::regclass,GREATEST(top_id,nextval(seq::regclass)),true);
 END LOOP;
END $$;
COMMIT;
