INSERT INTO public.project_applications (id,project_id,applicant_member_id,job_role,introduction,status,rejection_reason,applied_at,processed_at,cancelled_at,created_at,updated_at) VALUES (1, 6, -910001, 'BACKEND', 'DevLog에서 API 연동과 오류 상태 처리를 담당했습니다. 이번에는 거래 내역 조회와 입력 검증을 백엔드 팀과 함께 설계하고 싶습니다. 평일 저녁과 주말에 참여할 수 있습니다.', 'PENDING', NULL, '2026-10-30 10:00:00', NULL, NULL, '2026-10-30 10:00:00', '2026-10-30 10:00:00');
INSERT INTO public.project_applications (id,project_id,applicant_member_id,job_role,introduction,status,rejection_reason,applied_at,processed_at,cancelled_at,created_at,updated_at) VALUES (2, 6, -910004, 'BACKEND', 'Java와 Spring Boot로 거래 조회 계약과 공통 오류 응답을 설계한 경험이 있습니다. 금액·기간 경계값 테스트와 API 문서화를 맡고, 매주 코드 리뷰에 참여하겠습니다.', 'PENDING', NULL, '2026-10-31 19:30:00', NULL, NULL, '2026-10-31 19:30:00', '2026-10-31 19:30:00');
INSERT INTO public.project_applications (id,project_id,applicant_member_id,job_role,introduction,status,rejection_reason,applied_at,processed_at,cancelled_at,created_at,updated_at) VALUES (3, 8, -910001, 'FRONTEND', 'React와 TypeScript로 회고 작성·수정 흐름을 구현했습니다. 코드 리뷰 게시판과 프로필 화면을 맡고 싶습니다. 키보드 접근성과 모바일 레이아웃도 함께 점검하겠습니다.', 'PENDING', NULL, '2026-10-29 20:00:00', NULL, NULL, '2026-10-29 20:00:00', '2026-10-29 20:00:00');
INSERT INTO public.project_applications (id,project_id,applicant_member_id,job_role,introduction,status,rejection_reason,applied_at,processed_at,cancelled_at,created_at,updated_at) VALUES (4, 8, -910003, 'FRONTEND', '공통 컴포넌트와 디자인 토큰을 설계한 경험을 커뮤니티에 적용하고 싶습니다. 게시글·댓글 입력 패턴과 빈 상태 화면을 정리하고, 디자이너와 사용성 리뷰를 진행할 수 있습니다.', 'PENDING', NULL, '2026-10-30 13:00:00', NULL, NULL, '2026-10-30 13:00:00', '2026-10-30 13:00:00');
INSERT INTO public.project_applications (id,project_id,applicant_member_id,job_role,introduction,status,rejection_reason,applied_at,processed_at,cancelled_at,created_at,updated_at) VALUES (5, 8, -910004, 'BACKEND', '게시글 검색과 댓글 데이터 계약 설계에 관심이 있어 지원했습니다. 이번 모집은 주간 회의 참여 시간이 맞지 않아 검토가 종료된 데모 사례입니다.', 'REJECTED', '주간 회의 참여 시간이 맞지 않아 이번 모집에서는 함께하기 어렵습니다.', '2026-10-27 18:00:00', '2026-10-29 12:00:00', NULL, '2026-10-27 18:00:00', '2026-10-29 12:00:00');
INSERT INTO public.project_applications (id,project_id,applicant_member_id,job_role,introduction,status,rejection_reason,applied_at,processed_at,cancelled_at,created_at,updated_at) VALUES (6, 7, -910003, 'FRONTEND', '학습 진도와 피드백 화면의 일관된 UI를 만들고 싶어 지원했습니다. 다른 프로젝트 일정과 겹쳐 직접 지원을 취소한 데모 사례입니다.', 'CANCELLED', NULL, '2026-10-28 17:00:00', NULL, '2026-10-30 09:00:00', '2026-10-28 17:00:00', '2026-10-30 09:00:00');
